      /* (2603) values_query_tail ::= */ yytestcase(yyruleno==2603);
      /* (2611) values_into_optional_tail ::= */ yytestcase(yyruleno==2611);
      /* (2617) values_limit_optional_tail ::= */ yytestcase(yyruleno==2617);
      /* (2637) values_order_direction ::= */ yytestcase(yyruleno==2637);
      /* (2645) execute_tail ::= */ yytestcase(yyruleno==2645);
      /* (2652) diagnostics_area_tail ::= */ yytestcase(yyruleno==2652);
      /* (2695) signal_sqlstate_value_tail ::= */ yytestcase(yyruleno==2695);
      /* (2698) signal_set_tail ::= */ yytestcase(yyruleno==2698);
